theme.css:
/* theme: Summit Shadows | Three leaders meet, markets watch, and a boardroom falls — a page of quiet alarm in cold steel blues under a single amber threat line. */
/* mood: tense */
/* layout: hero=split; major-events=tile/grid-3; political-news=timeline/stack; financial-news=stat/stack; tech-news=outline/grid-2; entertainment-news=numbered/masonry; sports=banner/grid-2; music-releases=plain/stack; stock-analysis=stat/grid-3; outlook=plain/stack */

.diary-page {
  --paper: #fbf3e0;
  --paper-alt: #f3e4c8;
  --ink: #1f1610;
  --ink-soft: #3d2f22;
  --muted: #6b5a48;
  --accent: #8f4000;
  --accent-ink: #fff7e8;
  --rule: #d8c39a;
  --font-display: var(--ff-dm-serif), Georgia, serif;
  --font-body: var(--ff-newsreader), Georgia, serif;
  --font-ui: var(--ff-space-grotesk), system-ui, sans-serif;

  background-color: var(--paper);
  background-image:
    linear-gradient(135deg, transparent 0 48%, var(--rule) 48% 49%, transparent 49% 100%),
    linear-gradient(45deg, transparent 0 58%, var(--rule) 58% 59%, transparent 59% 100%);
  background-size: 120px 120px, 180px 180px;
}

.diary-page .diary-hero {
  background: linear-gradient(180deg, var(--paper-alt) 0%, var(--paper) 100%);
  border-bottom: 4px double var(--accent);
}

.diary-page .diary-kicker {
  letter-spacing: 0.3em;
  font-weight: 700;
  color: var(--accent);
}

.diary-page .diary-title {
  font-family: var(--font-display);
  font-weight: 400;
  font-size: clamp(2.5rem, 6vw, 5rem);
  letter-spacing: 0.01em;
  text-transform: uppercase;
  color: var(--ink);
}

.diary-page .diary-summary {
  font-style: italic;
  color: var(--ink-soft);
}

.diary-page .diary-theme-name {
  background: var(--accent);
  color: var(--accent-ink);
  letter-spacing: 0.08em;
}

.diary-page .diary-theme-note {
  font-family: var(--font-ui);
}

.diary-page .diary-toc {
  border-bottom: 1px solid var(--rule);
  background: color-mix(in srgb, var(--paper) 92%, transparent);
}

.diary-page .diary-toc-link.is-active {
  color: var(--accent);
}

.diary-page .diary-toc-number {
  color: var(--accent);
  font-family: var(--font-ui);
}

.diary-page .diary-section {
  border-top: 1px solid var(--rule);
}

.diary-page .diary-section-head {
  border-bottom: 3px solid var(--accent);
  padding-bottom: 0.75rem;
  margin-bottom: 2rem;
}

.diary-page .diary-section-number {
  font-size: 1.1rem;
  font-weight: 700;
  letter-spacing: 0.2em;
  color: var(--accent);
}

.diary-page .diary-section-title {
  font-family: var(--font-display);
  font-weight: 400;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--ink);
}

.diary-page .diary-card-title {
  font-family: var(--font-display);
  font-weight: 400;
  letter-spacing: 0.01em;
  color: var(--ink);
}

.diary-page .diary-card-body {
  color: var(--ink-soft);
}

.diary-page .diary-prose {
  color: var(--ink-soft);
}

.diary-page .diary-prose a {
  color: var(--accent);
}

.diary-page .diary-prose a:hover {
  color: var(--ink);
}

.diary-page .diary-prose strong {
  color: var(--ink);
}

.diary-page .diary-prose blockquote {
  border-left-color: var(--accent);
  color: var(--ink);
}

.diary-page .diary-prose ul > li::before {
  background: var(--accent);
}

.diary-page .diary-prose ol > li::marker {
  color: var(--accent);
}

.diary-page .diary-card-thread {
  border-color: var(--accent);
  color: var(--accent);
}

.diary-page .diary-card-thread:hover {
  background: var(--accent);
  color: var(--accent-ink);
}

/* Major Events: amber tile grid with a shared rail */
.diary-page [data-section="major-events"] .diary-card--tile .diary-card-inner {
  background: var(--paper-alt);
  border: 1px solid var(--rule);
  padding: 1.25rem;
  position: relative;
}

.diary-page [data-section="major-events"] .diary-card--tile .diary-card-title {
  font-size: 1.3rem;
  line-height: 1.25;
}

.diary-page [data-section="major-events"] .diary-card--tile .diary-card-body {
  font-size: 0.98rem;
  line-height: 1.6;
}

/* Political News: timeline on a rail */
.diary-page [data-section="political-news"] .diary-card--timeline .diary-card-inner {
  padding-left: 2rem;
}

.diary-page [data-section="political-news"] .diary-card--timeline .diary-card-inner::before {
  background: var(--rule);
}

.diary-page [data-section="political-news"] .diary-card--timeline .diary-card-inner::after {
  background: var(--accent);
  box-shadow: 0 0 0 4px var(--paper);
}

/* Financial News: one big stat */
.diary-page [data-section="financial-news"] .diary-card--stat .diary-card-inner {
  border-top-width: 4px;
  border-top-color: var(--accent);
}

.diary-page [data-section="financial-news"] .diary-card-figure {
  font-size: clamp(3rem, 12cqi, 5rem);
}

.diary-page .diary-card-figure {
  color: var(--accent);
}

.diary-page [data-section="financial-news"] .diary-card--stat .diary-card-body {
  font-size: 1.12rem;
}

/* Tech News: outlined with a left accent */
.diary-page [data-section="tech-news"] .diary-card--outline .diary-card-inner {
  border-left: 4px solid var(--accent);
  border-radius: 0;
  padding: 1rem 1.25rem;
}

.diary-page [data-section="tech-news"] .diary-card--outline .diary-card-title {
  font-size: 1.3rem;
}

/* Entertainment: numbered with an oversized numeral */
.diary-page [data-section="entertainment-news"] .diary-card--numbered .diary-card-index {
  color: var(--accent);
  font-size: 3.5rem;
}

/* Sports: banner with ink text */
.diary-page [data-section="sports"] .diary-card--banner .diary-card-inner {
  gap: 0;
  overflow: hidden;
  border: 1px solid var(--rule);
}

.diary-page [data-section="sports"] .diary-card--banner .diary-card-title {
  background: var(--ink);
  color: var(--paper);
  padding: 0.85rem 1.25rem;
  font-size: 1.15rem;
}

.diary-page [data-section="sports"] .diary-card--banner .diary-card-body {
  padding: 1.25rem;
  background: var(--paper-alt);
}

.diary-page [data-section="sports"] .diary-card--banner .diary-card-thread {
  margin: 1rem 1.25rem 0;
  border-color: var(--accent);
  color: var(--accent);
}

/* Music Releases: plain, no boxes */
.diary-page [data-section="music-releases"] .diary-card--plain .diary-card-inner {
  gap: 0.25rem;
}

.diary-page [data-section="music-releases"] .diary-card--plain .diary-card-body {
  font-size: 1rem;
}

/* Stock Analysis: stat numbers with a low bar, amber */
.diary-page [data-section="stock-analysis"] .diary-card--stat .diary-card-inner {
  border-top: 2px solid var(--accent);
}

.diary-page [data-section="stock-analysis"] .diary-card-figure {
  font-size: clamp(2rem, 10cqi, 2.75rem);
}

.diary-page .diary-spark {
  background: var(--paper-alt);
  border: 1px solid var(--rule);
}

.diary-page .diary-spark.is-up .diary-spark-change {
  color: var(--accent);
}

.diary-page .diary-spark.is-down .diary-spark-change {
  color: var(--accent);
}

.diary-page .diary-spark-line {
  stroke: var(--accent);
}

/* Outlook: quiet, no card, just text */
.diary-page [data-section="outlook"] .diary-card--plain .diary-card-inner {
  gap: 0.5rem;
  padding: 1.5rem;
  background: var(--paper-alt);
  border: 1px solid var(--rule);
}

.diary-page [data-section="outlook"] .diary-card--plain .diary-card-body {
  font-size: 1.1rem;
  line-height: 1.7;
}

/* Footer */
.diary-page .diary-footer {
  border-top: 1px solid var(--rule);
}

.diary-page .diary-footer a {
  color: var(--accent);
}

.diary-page .diary-footer a:hover {
  color: var(--ink);
}

/* Desktop sidebar: active link in accent */
@media (min-width: 1024px) {
  .diary-page .diary-toc-list {
    border-left-color: var(--rule);
  }

  .diary-page .diary-toc-link.is-active {
    border-left-color: var(--accent);
  }

  .diary-page .diary-toc-link:hover {
    color: var(--accent);
  }
}

/* Subtle entrance for cards, once */
.diary-page .diary-card {
  animation: diary-rise 600ms ease-out both;
}

.diary-page .diary-section:nth-of-type(2) .diary-card {
  animation-delay: 80ms;
}

.diary-page .diary-section:nth-of-type(3) .diary-card {
  animation-delay: 160ms;
}

@keyframes diary-rise {
  from {
    opacity: 0;
    transform: translateY(12px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
